INSERT INTO public.frameworks
  (id, org_id, name, short_name, version, category, issuing_body, jurisdiction,
INSERT INTO public.framework_controls
  (id, org_id, framework_id, control_ref, domain, title, description, control_type, priority)
VALUES
  ('fc-hitrust-00-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '00.a', 'Information Security Management Program', 'Information Security Management Program', 'An information security management program shall be established and maintained, defining the organization''s approach to managing information security and its implementation across the enterprise.', 'governance', 'high'),
  ('fc-hitrust-01-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.a', 'Access Control', 'Access Control Policy', 'An access control policy shall be established, documented, and reviewed based on business and information security requirements for access.', 'preventive', 'high'),
  ('fc-hitrust-01-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.b', 'Access Control', 'User Registration', 'A formal user registration and de-registration procedure shall be in place for granting and revoking access to all information systems and services.', 'preventive', 'high'),
  ('fc-hitrust-01-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.c', 'Access Control', 'Privilege Management', 'The allocation and use of privileges shall be restricted and controlled.', 'preventive', 'high'),
  ('fc-hitrust-01-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.d', 'Access Control', 'User Password Management', 'The allocation of passwords shall be controlled through a formal management process.', 'preventive', 'medium'),
  ('fc-hitrust-01-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.e', 'Access Control', 'Review of User Access Rights', 'Management shall review users access rights at regular intervals using a formal process.', 'detective', 'medium'),
  ('fc-hitrust-01-f', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.f', 'Access Control', 'Password Use', 'Users shall follow good security practices in the selection and use of passwords.', 'preventive', 'medium'),
  ('fc-hitrust-01-g', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.g', 'Access Control', 'Unattended User Equipment', 'Users shall ensure that unattended equipment has appropriate protection.', 'preventive', 'medium'),
  ('fc-hitrust-01-h', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.h', 'Access Control', 'Clear Desk and Clear Screen Policy', 'A clear desk policy for papers and removable storage media and a clear screen policy for information processing facilities shall be adopted.', 'preventive', 'low'),
  ('fc-hitrust-01-i', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.i', 'Access Control', 'Policy on the Use of Network Services', 'Users shall only be provided with access to the network and network services that they have been specifically authorized to use.', 'preventive', 'medium'),
  ('fc-hitrust-01-j', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.j', 'Access Control', 'User Authentication for External Connections', 'Appropriate authentication methods shall be used to control access by remote users.', 'technical', 'high'),
  ('fc-hitrust-01-k', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.k', 'Access Control', 'Equipment Identification in Networks', 'Automatic equipment identification shall be considered as a means to authenticate connections from specific locations and equipment.', 'technical', 'low'),
  ('fc-hitrust-01-l', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.l', 'Access Control', 'Remote Diagnostic and Configuration Port Protection', 'Physical and logical access to diagnostic and configuration ports shall be controlled.', 'preventive', 'medium'),
  ('fc-hitrust-01-m', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.m', 'Access Control', 'Segregation in Networks', 'Groups of information services, users, and information systems shall be segregated on networks.', 'preventive', 'medium'),
  ('fc-hitrust-01-n', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.n', 'Access Control', 'Network Connection Control', 'For shared networks, the capability of users to connect to the network shall be restricted in line with the access control policy.', 'preventive', 'medium'),
  ('fc-hitrust-01-o', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.o', 'Access Control', 'Network Routing Control', 'Routing controls shall be implemented for networks to ensure that computer connections and information flows do not breach the access control policy.', 'technical', 'medium'),
  ('fc-hitrust-01-p', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.p', 'Access Control', 'Secure Log-on Procedures', 'Access to operating systems shall be controlled by a secure log-on procedure.', 'technical', 'high'),
  ('fc-hitrust-01-q', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.q', 'Access Control', 'User Identification and Authentication', 'All users shall have a unique identifier for their personal use only, and a suitable authentication technique shall be chosen to substantiate the claimed identity of a user.', 'technical', 'high'),
  ('fc-hitrust-01-r', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.r', 'Access Control', 'Password Management System', 'Systems for managing passwords shall be interactive and shall ensure quality passwords.', 'technical', 'medium'),
  ('fc-hitrust-01-s', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.s', 'Access Control', 'Use of System Utilities', 'The use of utility programs that might be capable of overriding system and application controls shall be restricted and tightly controlled.', 'preventive', 'medium'),
  ('fc-hitrust-01-t', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.t', 'Access Control', 'Session Time-out', 'Inactive sessions shall shut down after a defined period of inactivity.', 'technical', 'medium'),
  ('fc-hitrust-01-u', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.u', 'Access Control', 'Limitation of Connection Time', 'Restrictions on connection times shall be used to provide additional security for high-risk applications.', 'technical', 'low'),
  ('fc-hitrust-01-v', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.v', 'Access Control', 'Information Access Restriction', 'Access to information and application system functions shall be restricted in accordance with the access control policy.', 'preventive', 'high'),
  ('fc-hitrust-01-w', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.w', 'Access Control', 'Sensitive System Isolation', 'Sensitive systems shall have a dedicated and isolated computing environment.', 'preventive', 'medium'),
  ('fc-hitrust-01-x', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.x', 'Access Control', 'Mobile Computing and Communications', 'A formal policy shall be in place, and appropriate security measures adopted, to protect against the risks of using mobile computing and communication facilities.', 'preventive', 'medium'),
  ('fc-hitrust-01-y', '00000000-0000-0000-0000-000000000001', 'hitrust', '01.y', 'Access Control', 'Teleworking', 'A policy, operational plans, and procedures shall be developed and implemented for teleworking activities.', 'preventive', 'medium'),
  ('fc-hitrust-02-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '02.a', 'Human Resources Security', 'Roles and Responsibilities', 'Security roles and responsibilities of employees, contractors, and third-party users shall be defined and documented in accordance with the organization''s information security policy.', 'administrative', 'medium'),
  ('fc-hitrust-02-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '02.b', 'Human Resources Security', 'Screening', 'Background verification checks on all candidates for employment, contractors, and third-party users shall be carried out in accordance with relevant laws, regulations, and ethics, and proportional to the business requirements.', 'administrative', 'high'),
  ('fc-hitrust-02-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '02.c', 'Human Resources Security', 'Terms and Conditions of Employment', 'As part of their contractual obligation, employees, contractors, and third-party users shall agree to and sign the terms and conditions of their employment contract, which shall state their and the organization''s responsibilities for information security.', 'administrative', 'medium'),
  ('fc-hitrust-02-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '02.d', 'Human Resources Security', 'Management Responsibilities', 'Management shall require employees, contractors, and third-party users to apply security in accordance with the established policies and procedures of the organization.', 'administrative', 'high'),
  ('fc-hitrust-02-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '02.e', 'Human Resources Security', 'Information Security Awareness, Education, and Training', 'All employees of the organization and, where relevant, contractors and third-party users shall receive appropriate awareness training and regular updates in organizational policies and procedures as relevant for their job function.', 'administrative', 'high'),
  ('fc-hitrust-02-f', '00000000-0000-0000-0000-000000000001', 'hitrust', '02.f', 'Human Resources Security', 'Disciplinary Process', 'There shall be a formal disciplinary process for employees who have committed a security breach.', 'corrective', 'medium'),
  ('fc-hitrust-02-g', '00000000-0000-0000-0000-000000000001', 'hitrust', '02.g', 'Human Resources Security', 'Termination or Change Responsibilities', 'Responsibilities for performing employment termination or change of employment shall be clearly defined and assigned.', 'administrative', 'medium'),
  ('fc-hitrust-02-h', '00000000-0000-0000-0000-000000000001', 'hitrust', '02.h', 'Human Resources Security', 'Return of Assets', 'All employees, contractors, and third-party users shall return all of the organizations assets in their possession upon termination of their employment, contract, or agreement.', 'preventive', 'medium'),
  ('fc-hitrust-02-i', '00000000-0000-0000-0000-000000000001', 'hitrust', '02.i', 'Human Resources Security', 'Removal of Access Rights', 'The access rights of all employees, contractors, and third-party users to information and information processing facilities shall be removed upon termination of their employment, contract, or agreement, or adjusted upon change.', 'preventive', 'high'),
  ('fc-hitrust-03-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '03.a', 'Risk Management', 'Risk Management Program Development', 'A formal information security risk management program shall be developed and implemented to identify, assess, and appropriately manage risks to the organizations information assets.', 'governance', 'high'),
  ('fc-hitrust-03-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '03.b', 'Risk Management', 'Performing Risk Assessments', 'Risk assessments shall be performed to identify and quantify risks to the organizations information assets on a periodic basis and when significant changes occur.', 'detective', 'high'),
  ('fc-hitrust-03-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '03.c', 'Risk Management', 'Risk Mitigation', 'Appropriate risk treatment options shall be selected and controls implemented to reduce identified risks to an acceptable level.', 'corrective', 'high'),
  ('fc-hitrust-03-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '03.d', 'Risk Management', 'Risk Evaluation', 'Risks shall be evaluated against defined risk acceptance criteria, and residual risk shall be formally reviewed and accepted by management.', 'governance', 'medium'),
  ('fc-hitrust-04-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '04.a', 'Security Policy', 'Information Security Policy Document', 'An information security policy document shall be approved by management, and published and communicated to all employees and relevant external parties.', 'governance', 'high'),
  ('fc-hitrust-04-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '04.b', 'Security Policy', 'Review of the Information Security Policy', 'The information security policy shall be reviewed at planned intervals, or if significant changes occur, to ensure its continuing suitability, adequacy, and effectiveness.', 'governance', 'medium'),
  ('fc-hitrust-05-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.a', 'Organization of Information Security', 'Management Commitment to Information Security', 'Management shall actively support security within the organization through clear direction, demonstrated commitment, explicit assignment, and acknowledgment of information security responsibilities.', 'governance', 'high'),
  ('fc-hitrust-05-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.b', 'Organization of Information Security', 'Information Security Coordination', 'Information security activities shall be coordinated by representatives from different parts of the organization with relevant roles and job functions.', 'governance', 'medium'),
  ('fc-hitrust-05-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.c', 'Organization of Information Security', 'Allocation of Information Security Responsibilities', 'All information security responsibilities shall be clearly defined and allocated.', 'governance', 'high'),
  ('fc-hitrust-05-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.d', 'Organization of Information Security', 'Authorization Process for Information Assets and Facilities', 'A management authorization process for new information processing facilities shall be defined and implemented.', 'preventive', 'medium'),
  ('fc-hitrust-05-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.e', 'Organization of Information Security', 'Confidentiality Agreements', 'Requirements for confidentiality or non-disclosure agreements reflecting the organization''s needs for the protection of information shall be identified and regularly reviewed.', 'administrative', 'medium'),
  ('fc-hitrust-05-f', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.f', 'Organization of Information Security', 'Contact with Authorities', 'Appropriate contacts with relevant authorities shall be maintained.', 'administrative', 'low'),
  ('fc-hitrust-05-g', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.g', 'Organization of Information Security', 'Contact with Special Interest Groups', 'Appropriate contacts with special interest groups, specialist security forums, and professional associations shall be maintained.', 'administrative', 'low'),
  ('fc-hitrust-05-h', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.h', 'Organization of Information Security', 'Independent Review of Information Security', 'The organization''s approach to managing information security and its implementation shall be reviewed independently at planned intervals, or when significant changes to the security implementation occur.', 'detective', 'medium'),
  ('fc-hitrust-05-i', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.i', 'Organization of Information Security', 'Identification of Risks Related to External Parties', 'The risks to the organization''s information and information processing facilities from business processes involving external parties shall be identified and appropriate controls implemented before granting access.', 'preventive', 'high'),
  ('fc-hitrust-05-j', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.j', 'Organization of Information Security', 'Addressing Security When Dealing with Customers', 'All identified security requirements shall be addressed before giving customers access to the organization''s information or assets.', 'preventive', 'medium'),
  ('fc-hitrust-05-k', '00000000-0000-0000-0000-000000000001', 'hitrust', '05.k', 'Organization of Information Security', 'Addressing Security in Third Party Agreements', 'Agreements with third parties involving accessing, processing, communicating, or managing the organization''s information or information processing facilities shall cover all relevant security requirements.', 'preventive', 'high'),
  ('fc-hitrust-06-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.a', 'Compliance', 'Identification of Applicable Legislation', 'All relevant statutory, regulatory, and contractual requirements and the organization''s approach to meet these requirements shall be explicitly defined, documented, and kept up to date for each information system and the organization.', 'administrative', 'high'),
  ('fc-hitrust-06-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.b', 'Compliance', 'Intellectual Property Rights', 'Appropriate procedures shall be implemented to ensure compliance with legislative, regulatory, and contractual requirements on the use of material that may be subject to intellectual property rights and on the use of proprietary software products.', 'administrative', 'medium'),
  ('fc-hitrust-06-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.c', 'Compliance', 'Protection of Organizational Records', 'Important records shall be protected from loss, destruction, and falsification, in accordance with statutory, regulatory, contractual, and business requirements.', 'preventive', 'high'),
  ('fc-hitrust-06-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.d', 'Compliance', 'Data Protection and Privacy of Covered Information', 'Data protection and privacy shall be ensured as required in relevant legislation, regulations, and, if applicable, contractual clauses.', 'preventive', 'high'),
  ('fc-hitrust-06-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.e', 'Compliance', 'Prevention of Misuse of Information Assets', 'Users shall be deterred from using information processing facilities for unauthorized purposes.', 'preventive', 'medium'),
  ('fc-hitrust-06-f', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.f', 'Compliance', 'Regulation of Cryptographic Controls', 'Cryptographic controls shall be used in compliance with all relevant agreements, laws, and regulations.', 'administrative', 'medium'),
  ('fc-hitrust-06-g', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.g', 'Compliance', 'Compliance with Security Policies and Standards', 'Managers shall ensure that all security procedures within their area of responsibility are carried out correctly to achieve compliance with security policies and standards.', 'detective', 'medium'),
  ('fc-hitrust-06-h', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.h', 'Compliance', 'Technical Compliance Checking', 'Information systems shall be regularly checked for compliance with security implementation standards.', 'detective', 'medium'),
  ('fc-hitrust-06-i', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.i', 'Compliance', 'Information Systems Audit Controls', 'Audit requirements and activities involving checks on operational systems shall be carefully planned and agreed upon to minimize the risk of disruptions to business processes.', 'detective', 'medium'),
  ('fc-hitrust-06-j', '00000000-0000-0000-0000-000000000001', 'hitrust', '06.j', 'Compliance', 'Protection of Information Systems Audit Tools', 'Access to information systems audit tools shall be protected to prevent any possible misuse or compromise.', 'preventive', 'medium'),
  ('fc-hitrust-07-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '07.a', 'Asset Management', 'Inventory of Assets', 'All assets shall be clearly identified and an inventory of all important assets drawn up and maintained.', 'preventive', 'high'),
  ('fc-hitrust-07-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '07.b', 'Asset Management', 'Ownership of Assets', 'All information and assets associated with information processing facilities shall be owned by a designated part of the organization.', 'administrative', 'medium'),
  ('fc-hitrust-07-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '07.c', 'Asset Management', 'Acceptable Use of Assets', 'Rules for the acceptable use of information and assets associated with information processing facilities shall be identified, documented, and implemented.', 'administrative', 'medium'),
  ('fc-hitrust-07-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '07.d', 'Asset Management', 'Classification Guidelines', 'Information shall be classified in terms of its value, legal requirements, sensitivity, and criticality to the organization.', 'preventive', 'high'),
  ('fc-hitrust-07-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '07.e', 'Asset Management', 'Information Labeling and Handling', 'An appropriate set of procedures for information labeling and handling shall be developed and implemented in accordance with the classification scheme adopted by the organization.', 'preventive', 'medium'),
  ('fc-hitrust-08-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.a', 'Physical and Environmental Security', 'Physical Security Perimeter', 'Security perimeters shall be used to protect areas that contain information and information processing facilities.', 'physical', 'high'),
  ('fc-hitrust-08-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.b', 'Physical and Environmental Security', 'Physical Entry Controls', 'Secure areas shall be protected by appropriate entry controls to ensure that only authorized personnel are allowed access.', 'physical', 'high'),
  ('fc-hitrust-08-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.c', 'Physical and Environmental Security', 'Securing Offices, Rooms, and Facilities', 'Physical security for offices, rooms, and facilities shall be designed and applied.', 'physical', 'medium'),
  ('fc-hitrust-08-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.d', 'Physical and Environmental Security', 'Protecting Against External and Environmental Threats', 'Physical protection against damage from fire, flood, earthquake, explosion, civil unrest, and other forms of natural or man-made disaster shall be designed and applied.', 'physical', 'medium'),
  ('fc-hitrust-08-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.e', 'Physical and Environmental Security', 'Working in Secure Areas', 'Physical protection and guidelines for working in secure areas shall be designed and applied.', 'physical', 'medium'),
  ('fc-hitrust-08-f', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.f', 'Physical and Environmental Security', 'Public Access, Delivery, and Loading Areas', 'Access points such as delivery and loading areas and other points where unauthorized persons may enter the premises shall be controlled and, if possible, isolated from information processing facilities to avoid unauthorized access.', 'physical', 'medium'),
  ('fc-hitrust-08-g', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.g', 'Physical and Environmental Security', 'Equipment Siting and Protection', 'Equipment shall be sited or protected to reduce the risks from environmental threats and hazards, and opportunities for unauthorized access.', 'physical', 'medium'),
  ('fc-hitrust-08-h', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.h', 'Physical and Environmental Security', 'Supporting Utilities', 'Equipment shall be protected from power failures and other disruptions caused by failures in supporting utilities.', 'physical', 'medium'),
  ('fc-hitrust-08-i', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.i', 'Physical and Environmental Security', 'Cabling Security', 'Power and telecommunications cabling carrying data or supporting information services shall be protected from interception or damage.', 'physical', 'medium'),
  ('fc-hitrust-08-j', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.j', 'Physical and Environmental Security', 'Equipment Maintenance', 'Equipment shall be correctly maintained to ensure its continued availability and integrity.', 'preventive', 'medium'),
  ('fc-hitrust-08-k', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.k', 'Physical and Environmental Security', 'Security of Equipment Off-Premises', 'Security shall be applied to off-site equipment taking into account the different risks of working outside the organizations premises.', 'physical', 'medium'),
  ('fc-hitrust-08-l', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.l', 'Physical and Environmental Security', 'Secure Disposal or Re-Use of Equipment', 'All items of equipment containing storage media shall be checked to ensure that any sensitive data and licensed software has been removed or securely overwritten prior to disposal or re-use.', 'preventive', 'high'),
  ('fc-hitrust-08-m', '00000000-0000-0000-0000-000000000001', 'hitrust', '08.m', 'Physical and Environmental Security', 'Removal of Property', 'Equipment, information, or software shall not be taken off-site without prior authorization.', 'preventive', 'medium'),
  ('fc-hitrust-09-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.a', 'Communications and Operations Management', 'Documented Operations Procedures', 'Operating procedures shall be documented, maintained, and made available to all users who need them.', 'administrative', 'medium'),
  ('fc-hitrust-09-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.b', 'Communications and Operations Management', 'Change Management', 'Changes to information processing facilities and systems shall be controlled.', 'preventive', 'high'),
  ('fc-hitrust-09-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.c', 'Communications and Operations Management', 'Segregation of Duties', 'Duties and areas of responsibility shall be segregated to reduce opportunities for unauthorized or unintentional modification or misuse of the organization''s assets.', 'preventive', 'high'),
  ('fc-hitrust-09-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.d', 'Communications and Operations Management', 'Separation of Development, Test, and Operational Environments', 'Development, test, and operational facilities shall be separated to reduce the risks of unauthorized access or changes to the operational system.', 'preventive', 'medium'),
  ('fc-hitrust-09-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.e', 'Communications and Operations Management', 'Service Delivery', 'It shall be ensured that the security controls, service definitions, and delivery levels included in the third-party service delivery agreement are implemented, operated, and maintained by the third party.', 'preventive', 'medium'),
  ('fc-hitrust-09-f', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.f', 'Communications and Operations Management', 'Monitoring and Review of Third Party Services', 'The services, reports, and records provided by the third party shall be regularly monitored and reviewed, and audits shall be carried out regularly.', 'detective', 'medium'),
  ('fc-hitrust-09-g', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.g', 'Communications and Operations Management', 'Managing Changes to Third Party Services', 'Changes to the provision of services, including maintaining and improving existing security policies, procedures, and controls, shall be managed, taking account of the criticality of business systems and processes involved and re-assessment of risks.', 'preventive', 'medium'),
  ('fc-hitrust-09-h', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.h', 'Communications and Operations Management', 'Capacity Management', 'The use of resources shall be monitored and tuned, and projections made of future capacity requirements to ensure the required system performance.', 'detective', 'medium'),
  ('fc-hitrust-09-i', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.i', 'Communications and Operations Management', 'System Acceptance', 'Acceptance criteria for new information systems, upgrades, and new versions shall be established, and suitable tests of the system(s) carried out during development and prior to acceptance.', 'preventive', 'medium'),
  ('fc-hitrust-09-j', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.j', 'Communications and Operations Management', 'Controls Against Malicious Code', 'Detection, prevention, and recovery controls to protect against malicious code, and appropriate user awareness procedures, shall be implemented.', 'detective', 'high'),
  ('fc-hitrust-09-k', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.k', 'Communications and Operations Management', 'Controls Against Mobile Code', 'Where the use of mobile code is authorized, the configuration shall ensure that the authorized mobile code operates according to a clearly defined security policy, and unauthorized mobile code shall be prevented from executing.', 'preventive', 'medium'),
  ('fc-hitrust-09-l', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.l', 'Communications and Operations Management', 'Back-up', 'Back-up copies of information and software shall be taken and tested regularly in accordance with the agreed backup policy.', 'corrective', 'high'),
  ('fc-hitrust-09-m', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.m', 'Communications and Operations Management', 'Network Controls', 'Networks shall be adequately managed and controlled in order to be protected from threats, and to maintain security for the systems and applications using the network, including information in transit.', 'preventive', 'high'),
  ('fc-hitrust-09-n', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.n', 'Communications and Operations Management', 'Security of Network Services', 'Security features, service levels, and management requirements of all network services shall be identified and included in any network services agreement, whether these services are provided in-house or outsourced.', 'preventive', 'medium'),
  ('fc-hitrust-09-o', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.o', 'Communications and Operations Management', 'Management of Removable Media', 'There shall be procedures in place for the management of removable media.', 'preventive', 'medium'),
  ('fc-hitrust-09-p', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.p', 'Communications and Operations Management', 'Disposal of Media', 'Media shall be disposed of securely and safely when no longer required, using formal procedures.', 'preventive', 'medium'),
  ('fc-hitrust-09-q', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.q', 'Communications and Operations Management', 'Information Handling Procedures', 'Procedures for the handling and storage of information shall be established to protect this information from unauthorized disclosure or misuse.', 'preventive', 'medium'),
  ('fc-hitrust-09-r', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.r', 'Communications and Operations Management', 'Security of System Documentation', 'System documentation shall be protected against unauthorized access.', 'preventive', 'low'),
  ('fc-hitrust-09-s', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.s', 'Communications and Operations Management', 'Information Exchange Policies and Procedures', 'Formal exchange policies, procedures, and controls shall be in place to protect the exchange of information through the use of all types of communication facilities.', 'preventive', 'medium'),
  ('fc-hitrust-09-t', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.t', 'Communications and Operations Management', 'Exchange Agreements', 'Agreements shall be established for the exchange of information and software between the organization and external parties.', 'administrative', 'medium'),
  ('fc-hitrust-09-u', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.u', 'Communications and Operations Management', 'Physical Media in Transit', 'Media containing information shall be protected against unauthorized access, misuse, or corruption during transportation beyond an organization''s physical boundaries.', 'physical', 'medium'),
  ('fc-hitrust-09-v', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.v', 'Communications and Operations Management', 'Electronic Messaging', 'Information involved in electronic messaging shall be appropriately protected.', 'preventive', 'medium'),
  ('fc-hitrust-09-w', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.w', 'Communications and Operations Management', 'Interconnected Business Information Systems', 'Policies and procedures shall be developed and implemented to protect information associated with the interconnection of business information systems.', 'preventive', 'medium'),
  ('fc-hitrust-09-x', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.x', 'Communications and Operations Management', 'Electronic Commerce Services', 'Information involved in electronic commerce passing over public networks shall be protected from fraudulent activity, contract dispute, and unauthorized disclosure and modification.', 'technical', 'high'),
  ('fc-hitrust-09-y', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.y', 'Communications and Operations Management', 'On-line Transactions', 'Information involved in on-line transactions shall be protected to prevent incomplete transmission, mis-routing, unauthorized message alteration, unauthorized disclosure, unauthorized message duplication, or replay.', 'technical', 'high'),
  ('fc-hitrust-09-z', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.z', 'Communications and Operations Management', 'Publicly Available Information', 'The integrity of information being made available on a publicly available system shall be protected to prevent unauthorized modification.', 'preventive', 'medium'),
  ('fc-hitrust-09-aa', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.aa', 'Communications and Operations Management', 'Audit Logging', 'Audit logs recording user activities, exceptions, and information security events shall be produced and kept for an agreed period to assist in future investigations and access control monitoring.', 'detective', 'high'),
  ('fc-hitrust-09-ab', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.ab', 'Communications and Operations Management', 'Monitoring System Use', 'Procedures for monitoring use of information processing facilities shall be established and the results of the monitoring activities reviewed regularly.', 'detective', 'high'),
  ('fc-hitrust-09-ac', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.ac', 'Communications and Operations Management', 'Protection of Log Information', 'Logging facilities and log information shall be protected against tampering and unauthorized access.', 'preventive', 'high'),
  ('fc-hitrust-09-ad', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.ad', 'Communications and Operations Management', 'Administrator and Operator Logs', 'System administrator and system operator activities shall be logged.', 'detective', 'medium'),
  ('fc-hitrust-09-ae', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.ae', 'Communications and Operations Management', 'Fault Logging', 'Faults shall be logged, analyzed, and appropriate action taken.', 'detective', 'medium'),
  ('fc-hitrust-09-af', '00000000-0000-0000-0000-000000000001', 'hitrust', '09.af', 'Communications and Operations Management', 'Clock Synchronization', 'The clocks of all relevant information processing systems within an organization or security domain shall be synchronized with an agreed accurate time source.', 'technical', 'medium'),
  ('fc-hitrust-10-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.a', 'Information Systems Acquisition, Development, and Maintenance', 'Security Requirements Analysis and Specification', 'Statements of business requirements for new information systems, or enhancements to existing information systems, shall specify the requirements for security controls.', 'preventive', 'high'),
  ('fc-hitrust-10-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.b', 'Information Systems Acquisition, Development, and Maintenance', 'Input Data Validation', 'Data input to applications shall be validated to ensure that this data is correct and appropriate.', 'technical', 'medium'),
  ('fc-hitrust-10-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.c', 'Information Systems Acquisition, Development, and Maintenance', 'Control of Internal Processing', 'Validation checks shall be incorporated into applications to detect any corruption of information through processing errors or deliberate acts.', 'technical', 'medium'),
  ('fc-hitrust-10-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.d', 'Information Systems Acquisition, Development, and Maintenance', 'Message Integrity', 'Requirements for ensuring authenticity and protecting message integrity in applications shall be identified, and appropriate controls identified and implemented.', 'technical', 'medium'),
  ('fc-hitrust-10-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.e', 'Information Systems Acquisition, Development, and Maintenance', 'Output Data Validation', 'Data output from an application shall be validated to ensure that the processing of stored information is correct and appropriate to the circumstances.', 'technical', 'medium'),
  ('fc-hitrust-10-f', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.f', 'Information Systems Acquisition, Development, and Maintenance', 'Policy on the Use of Cryptographic Controls', 'A policy on the use of cryptographic controls for protection of information shall be developed and implemented.', 'technical', 'high'),
  ('fc-hitrust-10-g', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.g', 'Information Systems Acquisition, Development, and Maintenance', 'Key Management', 'Key management shall be in place to support the organization''s use of cryptographic techniques.', 'technical', 'high'),
  ('fc-hitrust-10-h', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.h', 'Information Systems Acquisition, Development, and Maintenance', 'Control of Operational Software', 'There shall be procedures in place to control the installation of software on operational systems.', 'preventive', 'medium'),
  ('fc-hitrust-10-i', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.i', 'Information Systems Acquisition, Development, and Maintenance', 'Protection of System Test Data', 'Test data shall be selected carefully, and protected and controlled.', 'preventive', 'medium'),
  ('fc-hitrust-10-j', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.j', 'Information Systems Acquisition, Development, and Maintenance', 'Access Control to Program Source Code', 'Access to program source code shall be restricted.', 'preventive', 'medium'),
  ('fc-hitrust-10-k', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.k', 'Information Systems Acquisition, Development, and Maintenance', 'Change Control Procedures', 'The implementation of changes shall be controlled by the use of formal change control procedures.', 'preventive', 'high'),
  ('fc-hitrust-10-l', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.l', 'Information Systems Acquisition, Development, and Maintenance', 'Outsourced Software Development', 'Outsourced software development shall be supervised and monitored by the organization.', 'preventive', 'medium'),
  ('fc-hitrust-10-m', '00000000-0000-0000-0000-000000000001', 'hitrust', '10.m', 'Information Systems Acquisition, Development, and Maintenance', 'Control of Technical Vulnerabilities', 'Timely information about technical vulnerabilities of information systems being used shall be obtained, the organization''s exposure to such vulnerabilities evaluated, and appropriate measures taken to address the associated risk.', 'corrective', 'high'),
  ('fc-hitrust-11-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '11.a', 'Information Security Incident Management', 'Reporting Information Security Events', 'Information security events shall be reported through appropriate management channels as quickly as possible.', 'detective', 'high'),
  ('fc-hitrust-11-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '11.b', 'Information Security Incident Management', 'Reporting Security Weaknesses', 'All employees, contractors, and third-party users of information systems and services shall be required to note and report any observed or suspected security weaknesses in systems or services.', 'detective', 'medium'),
  ('fc-hitrust-11-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '11.c', 'Information Security Incident Management', 'Responsibilities and Procedures', 'Management responsibilities and procedures shall be established to ensure a quick, effective, and orderly response to information security incidents.', 'corrective', 'high'),
  ('fc-hitrust-11-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '11.d', 'Information Security Incident Management', 'Learning from Information Security Incidents', 'There shall be mechanisms in place to enable the types, volumes, and costs of information security incidents to be quantified and monitored.', 'corrective', 'medium'),
  ('fc-hitrust-11-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '11.e', 'Information Security Incident Management', 'Collection of Evidence', 'Where a follow-up action against a person or organization after an information security incident involves legal action (either civil or criminal), evidence shall be collected, retained, and presented to conform to the rules for evidence laid down in the relevant jurisdiction(s).', 'detective', 'medium'),
  ('fc-hitrust-12-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '12.a', 'Business Continuity Management', 'Including Information Security in the Business Continuity Management Process', 'A managed process shall be developed and maintained for business continuity throughout the organization that addresses the information security requirements needed for the organization''s business continuity.', 'corrective', 'high'),
  ('fc-hitrust-12-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '12.b', 'Business Continuity Management', 'Business Continuity and Risk Assessment', 'Events that can cause interruptions to business processes shall be identified, along with the probability and impact of such interruptions and their consequences for information security.', 'detective', 'medium'),
  ('fc-hitrust-12-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '12.c', 'Business Continuity Management', 'Developing and Implementing Continuity Plans Including Information Security', 'Plans shall be developed and implemented to maintain or restore operations and ensure availability of information at the required level and in the required time scales following interruption to, or failure of, critical business processes.', 'corrective', 'high'),
  ('fc-hitrust-12-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '12.d', 'Business Continuity Management', 'Business Continuity Planning Framework', 'A single framework of business continuity plans shall be maintained to ensure all plans are consistent, to consistently address information security requirements, and to identify priorities for testing and maintenance.', 'corrective', 'medium'),
  ('fc-hitrust-12-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '12.e', 'Business Continuity Management', 'Testing, Maintaining, and Re-Assessing Business Continuity Plans', 'Business continuity plans shall be tested and updated regularly to ensure that they are up to date and effective.', 'detective', 'medium'),
  ('fc-hitrust-13-a', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.a', 'Privacy Practices', 'Privacy Notice', 'The organization shall provide notice of its information practices, including the purposes for which personal information is collected, used, retained, and disclosed, at or before the time of collection.', 'administrative', 'high'),
  ('fc-hitrust-13-b', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.b', 'Privacy Practices', 'Openness and Transparency', 'The organization shall maintain openness and transparency about developments, practices, and policies with respect to personal information.', 'governance', 'medium'),
  ('fc-hitrust-13-c', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.c', 'Privacy Practices', 'Accounting of Disclosures', 'The organization shall maintain an accounting of disclosures of personal information and make it available to the individual upon request.', 'detective', 'medium'),
  ('fc-hitrust-13-d', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.d', 'Privacy Practices', 'Consent', 'The organization shall obtain consent from individuals, where required, for the collection, use, and disclosure of their personal information.', 'administrative', 'high'),
  ('fc-hitrust-13-e', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.e', 'Privacy Practices', 'Choice', 'The organization shall provide individuals with appropriate choice regarding the collection, use, and disclosure of their personal information.', 'administrative', 'medium'),
  ('fc-hitrust-13-f', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.f', 'Privacy Practices', 'Principle Access', 'The organization shall provide individuals with the ability to access their personal information for review, and to update or correct it as appropriate.', 'preventive', 'medium'),
  ('fc-hitrust-13-g', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.g', 'Privacy Practices', 'Purpose Legitimacy', 'The organization shall ensure that the purposes for which personal information is collected are legitimate and comply with applicable legal and regulatory requirements.', 'governance', 'medium'),
  ('fc-hitrust-13-h', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.h', 'Privacy Practices', 'Purpose Specification', 'The organization shall specify the purposes for which personal information is collected at or before the time of collection.', 'administrative', 'medium'),
  ('fc-hitrust-13-i', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.i', 'Privacy Practices', 'Collection Limitation', 'The organization shall limit the collection of personal information to that which is necessary for the specified purposes.', 'preventive', 'high'),
  ('fc-hitrust-13-j', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.j', 'Privacy Practices', 'Data Minimization', 'The organization shall minimize the personal information it collects, uses, retains, and discloses to that which is directly relevant and necessary to accomplish the specified purposes.', 'preventive', 'high'),
  ('fc-hitrust-13-k', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.k', 'Privacy Practices', 'Use and Disclosure', 'The organization shall limit the use and disclosure of personal information to the purposes for which it was collected, except with consent of the individual or as required by law.', 'preventive', 'high'),
  ('fc-hitrust-13-l', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.l', 'Privacy Practices', 'Retention and Disposal', 'The organization shall retain personal information only as long as necessary to fulfill the stated purposes, and shall securely dispose of it thereafter.', 'preventive', 'medium'),
  ('fc-hitrust-13-m', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.m', 'Privacy Practices', 'Accuracy and Quality', 'The organization shall maintain personal information that is accurate, complete, and relevant for the purposes for which it is to be used.', 'preventive', 'medium'),
  ('fc-hitrust-13-n', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.n', 'Privacy Practices', 'Participation and Redress', 'The organization shall provide individuals with the ability to participate in decisions regarding their personal information and a means of redress for privacy concerns.', 'administrative', 'medium'),
  ('fc-hitrust-13-o', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.o', 'Privacy Practices', 'Complaint Management', 'The organization shall establish procedures for receiving, investigating, and responding to privacy-related complaints and disputes.', 'corrective', 'medium'),
  ('fc-hitrust-13-p', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.p', 'Privacy Practices', 'Governance', 'The organization shall establish a privacy governance structure with defined roles, responsibilities, and accountability for the protection of personal information.', 'governance', 'high'),
  ('fc-hitrust-13-q', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.q', 'Privacy Practices', 'Privacy and Impact Assessment', 'The organization shall conduct privacy risk and impact assessments for programs and systems that collect, use, or disclose personal information.', 'detective', 'high'),
  ('fc-hitrust-13-r', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.r', 'Privacy Practices', 'Privacy Requirements for Contractors and Processors', 'The organization shall establish privacy requirements for contractors and processors that handle personal information on its behalf, and monitor their compliance.', 'preventive', 'high'),
  ('fc-hitrust-13-s', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.s', 'Privacy Practices', 'Privacy Monitoring and Auditing', 'The organization shall monitor and audit its privacy practices for compliance with its privacy policies, procedures, and applicable legal requirements.', 'detective', 'medium'),
  ('fc-hitrust-13-t', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.t', 'Privacy Practices', 'Privacy Protection Awareness and Training', 'The organization shall provide privacy awareness and training to its workforce regarding the protection of personal information.', 'administrative', 'medium'),
  ('fc-hitrust-13-u', '00000000-0000-0000-0000-000000000001', 'hitrust', '13.u', 'Privacy Practices', 'Privacy Protection Reporting', 'The organization shall report on the status and effectiveness of its privacy program to management and, where required, to regulators and individuals.', 'detective', 'medium')
