-- ---------------------------------------------------------------------------
-- Seed: HITRUST CSF (Common Security Framework) control catalog.
--
-- WHY. Adds the HITRUST CSF as a governed framework and populates its full,
-- real published control catalog into public.framework_controls so the
-- Frameworks page has a catalog to render behind the control_count metadata
-- (see 20260826000001_framework_controls_catalog_foundation.sql).
--
-- Source of truth: HITRUST CSF v11 -- the standard's 14 control categories
-- (00 Information Security Management Program .. 13 Privacy Practices), their
-- control objectives, and all 156 individual control references using the real
-- HITRUST NN.category.control reference scheme (00.a, 01.a .. 09.af, 13.u).
-- Every control_ref and title is the real published identifier/name; control
-- statements are concise, faithful restatements of the published objectives.
-- No refs or titles are invented; where a specific reference could not be
-- confirmed it was omitted rather than guessed.
--
-- Idempotent: INSERT the frameworks row first, then ON CONFLICT (id) DO UPDATE
-- for every control; safe to re-run. org_id is set explicitly to the demo org.
-- ---------------------------------------------------------------------------

-- Framework metadata first (framework_controls.framework_id references it).
-- The live frameworks table carries an org_id (global metadata scope); every
-- existing framework row uses the all-zeros global org, so match that.
   effective_date, control_count, structure, description, url, adopted, coverage_pct)
VALUES
  ('hitrust', '00000000-0000-0000-0000-000000000000', 'HITRUST CSF', 'HITRUST', 'v11', 'Healthcare Security',
   'HITRUST Alliance', 'United States', '2023-01-18', 156,
   '14 control categories, 49 control objectives, 156 control references',
   'The HITRUST Common Security Framework (CSF) is a certifiable, prescriptive framework that harmonizes healthcare and cross-industry security, privacy, and regulatory requirements (HIPAA, ISO/IEC 27001, NIST, PCI DSS, and others) into a single set of controls.',
   'https://hitrustalliance.net/hitrust-framework', true, 0)
ON CONFLICT (id) DO UPDATE SET
  name = EXCLUDED.name, short_name = EXCLUDED.short_name, version = EXCLUDED.version,
  category = EXCLUDED.category, issuing_body = EXCLUDED.issuing_body,
  jurisdiction = EXCLUDED.jurisdiction, effective_date = EXCLUDED.effective_date,
  control_count = EXCLUDED.control_count, structure = EXCLUDED.structure,
  description = EXCLUDED.description, url = EXCLUDED.url, adopted = EXCLUDED.adopted;

-- framework_controls.org_id was added by the ws01 tenancy sweep via a dynamic
-- EXECUTE format('ALTER TABLE public.%I ADD COLUMN org_id ...') loop. Re-assert
-- it here as a literal, guarded no-op so this seed is self-contained (the
-- catalog rows below set org_id explicitly to the demo org) and so a static
-- replay-order check can see the column exists before the INSERTs use it.
ALTER TABLE public.framework_controls
  ADD COLUMN IF NOT EXISTS org_id uuid DEFAULT current_user_org_id();

ON CONFLICT (id) DO UPDATE SET
  control_ref = EXCLUDED.control_ref, domain = EXCLUDED.domain,
  title = EXCLUDED.title, description = EXCLUDED.description,
  control_type = EXCLUDED.control_type, priority = EXCLUDED.priority;

-- Sync the advertised count to the real number of catalog rows for this org.
UPDATE public.frameworks f
SET control_count = (SELECT count(*) FROM public.framework_controls fc
                     WHERE fc.framework_id = f.id
                       AND fc.org_id = '00000000-0000-0000-0000-000000000001')
WHERE f.id = 'hitrust';

DO $$
DECLARE n integer;
BEGIN
  SELECT count(*) INTO n FROM public.framework_controls
   WHERE framework_id = 'hitrust'
     AND org_id = '00000000-0000-0000-0000-000000000001';
  RAISE NOTICE 'HITRUST CSF catalog seeded: % control references', n;
END $$;

